#!/bin/bash
set -euo pipefail
umask 077
backup_dir=/var/backups/cellman
install -d -m 700 "$backup_dir"
target="$backup_dir/cellman-$(date -u +%Y%m%dT%H%M%SZ).dump"
runuser -u postgres -- pg_dump -Fc cellman > "$target.tmp"
pg_restore --list "$target.tmp" > /dev/null
mv "$target.tmp" "$target"
sha256sum "$target" > "$target.sha256"
# Restrict retention cleanup to files generated by this script in this exact directory.
find /var/backups/cellman -maxdepth 1 -type f -name 'cellman-*.dump' -mtime +14 -delete
find /var/backups/cellman -maxdepth 1 -type f -name 'cellman-*.dump.sha256' -mtime +14 -delete
echo "Database backup completed: $(basename "$target")"
